110:            var airtightEv = new AirtightChanged(airtight, airtight, true, pos);
111:            RaiseLocalEvent(airtight, ref airtightEv, true);
112:        }
113:
114:        public void UpdatePosition(Entity<AirtightComponent> ent, TransformComponent? xform = null)
115:        {
116:            var (owner, airtight) = ent;
117:            if (!Resolve(owner, ref xform))
118:                return;
119:
120:            if (!xform.Anchored || !TryComp(xform.GridUid, out MapGridComponent? grid))
121:                return;
122:
123:            var indices = _transform.GetGridTilePositionOrDefault((ent, xform), grid);
124:            airtight.LastPosition = (xform.GridUid.Value, indices);
125:            InvalidatePosition((xform.GridUid.Value, grid), indices);
126:        }
127:
128:        public void InvalidatePosition(Entity<MapGridComponent?> grid, Vector2i pos)
129:        {
130:            _explosionSystem.UpdateAirtightMap(grid, pos, grid);
131:            _atmosphereSystem.InvalidateTile(grid.Owner, pos);
132:        }
133:
134:        private AtmosDirection Rotate(AtmosDirection myDirection, Angle myAngle)
135:        {
136:            var newAirBlockedDirs = AtmosDirection.Invalid;
137:
138:            if (myAngle == Angle.Zero)
139:                return myDirection;
140:
141:            // TODO ATMOS MULTIZ: When we make multiZ atmos, special case this.
142:            for (var i = 0; i < Atmospherics.Directions; i++)
143:            {
144:                var direction = (AtmosDirection) (1 << i);
145:                if (!myDirection.IsFlagSet(direction))
146:                    continue;
147:                var angle = direction.ToAngle();
148:                angle += myAngle;
149:                newAirBlockedDirs |= angle.ToAtmosDirectionCardinal();
150:            }
151:
152:            return newAirBlockedDirs;
153:        }
154:    }
155:
156:    /// <summary>
157:    /// Raised upon the airtight status being changed via anchoring, movement, etc.
158:    /// </summary>
159:    /// <param name="Entity"></param>
160:    /// <param name="Airtight"></param>
161:    /// <param name="AirBlockedChanged">Whether the <see cref="AirtightComponent.AirBlocked"/> changed</param>
162:    /// <param name="Position"></param>
163:    [ByRefEvent]
164:    public readonly record struct AirtightChanged(EntityUid Entity, AirtightComponent Airtight, bool AirBlockedChanged, (EntityUid Grid, Vector2i Tile) Position);
165:}

